module Ulx3sTop (
input logic clk_25mhz,
input logic btn_pwr_n,
input logic ftdi_txd,
output logic ftdi_rxd,
output logic wifi_gpio0,
output logic [7:0] led
);
logic clk;
logic [15:0] cpu_rx_data;
logic [15:0] cpu_tx_status;
logic [15:0] debug_pc;
logic locked;
logic mmio_rx_pop;
logic reset;
logic rst_n;
logic [7:0] rxd;
logic rxd_strobe;
logic tx_busy_latch;
logic [7:0] txd;
logic txd_ready;
logic txd_strobe;
logic uart_rx_valid;
logic [7:0] uart_rxd_latch;
assign wifi_gpio0 = 1'h1;
Uart  uart(.clk(clk),.reset(reset),.serial_rxd(ftdi_txd),.txd(txd),.txd_strobe(txd_strobe),.serial_txd(ftdi_rxd),.rxd(rxd),.rxd_strobe(rxd_strobe),.txd_ready(txd_ready));
