CpuCore  cpu_core(.clk(clk),.rst_n(rst_n),.mmio_rx_data(cpu_rx_data),.mmio_tx_status(cpu_tx_status),.mmio_rx_pop(mmio_rx_pop),.mmio_tx_data(txd),.mmio_tx_strobe(txd_strobe),.debug_pc(debug_pc),.port_b_addr_out(),.port_b_wdata_out(),.port_b_we_out(),.port_b_en_out());
//  sequential
always_ff @(posedge clk) begin
  if(reset) begin
      uart_rx_valid <= 1'h0;
      uart_rxd_latch <= 8'h0;
  end   else begin
      if(rxd_strobe) begin
          uart_rxd_latch <= rxd;
          uart_rx_valid <= 1'h1;
      end       else begin
          if(mmio_rx_pop) begin
              uart_rx_valid <= 1'h0;
          end 

      end 

  end 

end

