uart_rx_valid, /*   15 */
7'h0, /* 14:8 */
uart_rxd_latch  /*  7:0 */
};  // swizzle
assign reset = ~rst_n;  // not_
assign rst_n = btn_pwr_n & locked;  // and_
//  sequential_0
always_ff @(posedge clk) begin
  if(reset) begin
      tx_busy_latch <= 1'h0;
  end   else begin
      if(txd_strobe) begin
          tx_busy_latch <= 1'h1;
      end       else begin
          if(txd_ready) begin
              tx_busy_latch <= 1'h0;
          end 

      end 

  end 

end

assign cpu_tx_status = tx_busy_latch ? 16'h1 : 16'h0;  // mux
assign led = {
locked, /*   7 */
(debug_pc[6:0])  /* 6:0 */
};  // swizzle_0
endmodule : Ulx3sTop